const items = $input.all();
const leads = $('⚙️ Select Batch + Country Route').all();
const now = new Date().toISOString();
const cooldownDate = new Date(Date.now() + 3 * 60 * 60 * 1000).toISOString();

return items.map((item, i) => {
  const resp = item.json || {};
  const lead = (leads[i] || leads[0]).json;

  const statusCode = resp.statusCode ?? resp.status ?? (resp.headers ? 200 : null);
  const body = resp.body ?? resp;
  const conversationId = body.conversation_id || body.conversationId || body.call_sid || body.callSid || '';

  let status, last_call_status, notes, callback_date;

  if (statusCode && statusCode >= 200 && statusCode < 300 && conversationId) {
    status = 'CALL_IN_PROGRESS';
    last_call_status = 'INITIATED';
    notes = '🟢 Dial sent: ' + conversationId;
    callback_date = '';
  } else if (statusCode && statusCode >= 400) {
    status = 'DIAL_FAILED';
    last_call_status = 'HTTP_' + statusCode;
    notes = '🔴 ElevenLabs ' + statusCode + ': ' + JSON.stringify(body).slice(0, 200);
    callback_date = cooldownDate;
  } else {
    status = 'DIAL_FAILED';
    last_call_status = 'NO_CONV_ID';
    notes = '🟡 Unexpected: ' + JSON.stringify(body).slice(0, 200);
    callback_date = cooldownDate;
  }

  console.log('📞 v5 —', lead.lead_id, '| HTTP', statusCode, '| status:', status, '| conv_id:', conversationId);

  return { json: {
    lead_id: lead.lead_id,
    country: lead.country,
    _source_country: lead._source_country || lead.country,
    _source_sheet: lead._source_sheet,
    country: lead.country,
    language: lead.language,
    elevenlabs_call_id: conversationId,
    status,
    last_call_status,
    notes,
    callback_date,
    call_attempts: Number(lead.call_attempts || 0) + 1,
    last_call_time: now
  }};
});

