const out=[];
for (const item of $input.all()) {
  const r={...(item.json||{})};
  r.country='nepal';
  // Nepal reutiliza temporalmente la configuración de idioma de India.
  // Cambiar aquí cuando se defina un idioma/agente dedicado.
