return out;

// MULTI-PAIS SAFE CONFIG — India + Nepal activos; slot3/slot4 listos pero apagados.
// Nepal REUTILIZA temporalmente el mismo agente/phone-number de India.
// Cuando tengas un agente/idioma dedicado, solo cambia este bloque.
const COUNTRY_CFG = {
  india: {
    enabled: true,
    aliases: ['india','in'],
    dialPrefix: '+91',
    sheet: 'leads',
    language: 'hi',
    agent_id: 'agent_5701kramx550e3qs2tm11661b48p',
    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6'
  },
  nepal: {
    enabled: true,
    aliases: ['nepal','np'],
    dialPrefix: '+977',
    sheet: 'leads nepal',
    language: 'hi',
    agent_id: 'agent_7601m209ntj3fyrbg0dcq6w507yq',
    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6'
  },
  slot3: {
    enabled: false,
    aliases: ['slot3'],
    dialPrefix: '',
    sheet: 'leads slot3',
    language: '',
    agent_id: '',
    agent_phone_number_id: ''
  },
  slot4: {
    enabled: false,
    aliases: ['slot4'],
    dialPrefix: '',
    sheet: 'leads slot4',
    language: '',
    agent_id: '',
    agent_phone_number_id: ''
  }
};

function canonicalCountry(rawCountry, rawPhone='') {
  const c = String(rawCountry || '').trim().toLowerCase();
  for (const [key,cfg] of Object.entries(COUNTRY_CFG)) {
    if (key === c || cfg.aliases.includes(c)) return key;
  }
  const p = String(rawPhone || '').replace(/[^0-9+]/g,'');
  if (p.startsWith('+977') || p.startsWith('977')) return 'nepal';
  if (p.startsWith('+91')  || p.startsWith('91'))  return 'india';
  return '';
}

function normalizePhone(rawPhone, countryKey) {
  let p = String(rawPhone || '').replace(/[^0-9+]/g, '');
  if (!p) return '';
  const cfg = COUNTRY_CFG[countryKey];
  if (!cfg || !cfg.dialPrefix) return p.startsWith('+') ? p : ('+' + p);
  const prefixDigits = cfg.dialPrefix.replace('+','');
  if (p.startsWith('+')) return p;
  if (p.startsWith(prefixDigits) && p.length > prefixDigits.length + 6) return '+' + p;
  return cfg.dialPrefix + p;
}

const SKIP_STATUSES = new Set([
  'DO_NOT_CALL', 'CONVERTED', 'MAX_ATTEMPTS_REACHED',
  'INTERESTED', 'NOT_INTERESTED', 'SALES_HANDOFF', 'ACCOUNT_OPENED',
  'SUCCESSFUL', 'VOICEMAIL', 'FAILED', 'SCHEDULED'
]);

const BATCH_SIZE = 4;             // capacidad actual preservada
const RETRY_COOLDOWN_MIN = 5;
const STUCK_TIMEOUT_MIN = 30;
const now = Date.now();

const attempts = [];
const skipped = [];

for (const item of $input.all()) {
  const r = { ...(item.json || {}) };
  let attemptsCount = Number(r.call_attempts || 0);
  let status = String(r.status || '').trim().toUpperCase();

  if (!r.lead_id || String(r.lead_id).trim() === '') {
    skipped.push({ lead_id:'EMPTY', reason:'missing lead_id' }); continue;
  }

  const country = canonicalCountry(r.country, r.phone);
  const cfg = COUNTRY_CFG[country];
  if (!country || !cfg) {
    skipped.push({ lead_id:r.lead_id, reason:'unsupported/missing country' }); continue;
  }
  if (!cfg.enabled) {
    skipped.push({ lead_id:r.lead_id, reason:`country ${country} disabled` }); continue;
  }

  const phone = normalizePhone(r.phone, country);
  if (!/^\+[1-9]\d{7,14}$/.test(phone)) {
    skipped.push({ lead_id:r.lead_id, reason:`bad phone: '${r.phone}'` }); continue;
  }

  if ((status === 'CALL_IN_PROGRESS' || status === 'DIALING') && r.last_call_time) {
    const minsSince = (now - new Date(r.last_call_time).getTime()) / 60000;
    if (minsSince > STUCK_TIMEOUT_MIN) {
      status = 'READY_TO_CALL'; r.status = 'READY_TO_CALL';
    } else {
      skipped.push({ lead_id:r.lead_id, reason:`${status} since ${minsSince.toFixed(0)}min` }); continue;
    }
  }

  if (status === 'DIAL_FAILED' && r.last_call_time) {
    const minsSince = (now - new Date(r.last_call_time).getTime()) / 60000;
    if (minsSince < RETRY_COOLDOWN_MIN) {
      skipped.push({ lead_id:r.lead_id, reason:`DIAL_FAILED cooldown ${minsSince.toFixed(1)}min` }); continue;
    }
    status = 'READY_TO_CALL'; r.status = 'READY_TO_CALL';
  }

  if (attemptsCount >= 3) {
    skipped.push({ lead_id:r.lead_id, reason:`attempts=${attemptsCount}` }); continue;
  }
  if (SKIP_STATUSES.has(status)) {
    skipped.push({ lead_id:r.lead_id, reason:`status=${status}` }); continue;
  }

  r.phone = phone;
  r.full_name = String(r.full_name || '').trim() || 'User';
  r.lead_id = String(r.lead_id).trim();
  r.country = country;
  r._source_country = String(r._source_country || country).toLowerCase();
  r._source_sheet = String(r._source_sheet || cfg.sheet || '').trim();
  if (!r._source_sheet) { skipped.push({ lead_id:r.lead_id, reason:`country ${country} missing source sheet` }); continue; }
  r.language = String(r.language || cfg.language || '').trim().toLowerCase();
  r._agent_id = cfg.agent_id;
  r._agent_phone_number_id = cfg.agent_phone_number_id;

  if (!r._agent_id || !r._agent_phone_number_id) {
    skipped.push({ lead_id:r.lead_id, reason:`country ${country} missing ElevenLabs route` }); continue;
  }

  attempts.push({ json:r });
}

console.log('🟢 ELEGIBLES', attempts.length, '| ⚪ SKIPPED', skipped.length, JSON.stringify(skipped));
if (!attempts.length) return [];

// Round-robin por país para que India no monopolice el batch cuando Nepal también tiene leads.
const order = ['india','nepal','slot3','slot4'].filter(c => COUNTRY_CFG[c].enabled);
const buckets = Object.fromEntries(order.map(c => [c, attempts.filter(a => a.json.country === c)]));
const batch = [];
let progress = true;
while (batch.length < BATCH_SIZE && progress) {
  progress = false;
  for (const c of order) {
    if (batch.length >= BATCH_SIZE) break;
    if (buckets[c].length) {
      batch.push(buckets[c].shift());
      progress = true;
    }
  }
}

console.log(`📦 Batch multi-país: ${batch.length}/${BATCH_SIZE} | ` + order.map(c => c+':'+attempts.filter(a=>a.json.country===c).length).join(' | '));
return batch;
